    expect({seenError, thrown}).toEqual({seenError: original, thrown: original});
  });

  it('preserves a plain object rejection as the cause', async () => {
    const reason = {code: 503};
    const {thrown, seenError} = await rejectionOutcome(reason);

    expect({thrown, cause: seenError?.cause}).toEqual({thrown: reason, cause: reason});
  });
});

