import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createChatOrchestrator} from './chatOrchestrator.js';

export const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

export const createRejectingProvider = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

export const createSession = (): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: '2024-01-01T00:00:00.000Z'}],
});

export const rejectionOutcome = async (reason: unknown) => {
  let seenError: Error | undefined;
  const session = createSession();
  const orchestrator = createChatOrchestrator(createRejectingProvider(reason), promptBuilder, undefined, {
    hooks: {onError: async (_session, error) => (seenError = error)},
  });
  const thrown = await orchestrator.processMessage(session).then(
    () => 'resolved',
    (value: unknown) => value
  );

  return {thrown, seenError};
};

